#!/usr/bin/env python3
"""Re-run Gate-3 BoundaryGuard healthy-path with archive multi-URL boundary.

Matches the paper Table VII workload (200 evenly spaced delivered Optimism
messages) under the production-recommended boundary fallback used in
boundary_fallback_reprobe.py. Writes tagged JSONL/summary for paper update.
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import argparse
import json
import time
from pathlib import Path

import relayer_proxy_live as harness
from boundaryguard_proxy import ProxyConfig


ROOT = _GITHUB_ROOT
# Production-style boundary candidates (Optimism). Exclude primary/repair URLs
# from the preferred head of the list to preserve role isolation.
OP_BOUNDARY_URLS = [
    "https://optimism.drpc.org",
    "https://optimism.gateway.tenderly.co",
    "https://optimism.llamarpc.com",
    "https://optimism-rpc.publicnode.com",
    "https://rpc.ankr.com/optimism",
]


def expected_count_any(
    urls: list[str],
    mailbox: str,
    start: int,
    end: int,
    *,
    lookup,
) -> int | None:
    for url in urls:
        value = lookup(url, mailbox, start, end)
        if value is not None:
            return value
    return None


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--limit", type=int, default=200)
    parser.add_argument("--port", type=int, default=18555)
    parser.add_argument("--tag", default="production200")
    args = parser.parse_args()

    cfg = {
        "primary": "https://mainnet.optimism.io",
        "boundary": OP_BOUNDARY_URLS[0],
        "repair": "https://op-pokt.nodies.app",
        "fallback": "https://optimism.drpc.org",
    }
    # Evaluation oracle uses the same multi-URL boundary pool.
    eval_boundary_urls = list(OP_BOUNDARY_URLS)

    messages = harness.load_messages("optimism", args.limit, recent=False)
    out = DATA / f"relayer_proxy_live_{args.tag}.jsonl"
    summary_path = DATA / f"relayer_proxy_live_{args.tag}_summary.json"
    trace_path = DATA / f"relayer_proxy_trace_{args.tag}.jsonl"
    compare_path = DATA / "relayer_proxy_production_compare.json"

    mailbox = harness.normalize(messages[0]["origin_mailbox"])
    proxy_cfg = ProxyConfig(
        chain_id="optimism",
        mailbox=mailbox,
        primary_url=cfg["primary"],
        boundary_url=cfg["boundary"],
        repair_url=cfg["repair"],
        boundary_urls=OP_BOUNDARY_URLS[1:],
        timeout_s=25.0,
        retry_count=1,
        chunk_count=4,
        confirmation_depth=0,
        finalized_tip=None,
        trace_path=str(trace_path),
    )
    server, proxy = harness.start_proxy(proxy_cfg, args.port)
    proxy_url = f"http://127.0.0.1:{args.port}"
    started = time.time()
    records: list[dict] = []
    try:
        # Monkey-patch expected_count for this run to use multi-URL oracle.
        # Keep a direct handle to the original lookup to avoid recursion.
        original_expected = harness.expected_count

        def multi_expected(url: str, mailbox: str, start: int, end: int) -> int | None:
            del url  # evaluation ignores the single cfg boundary URL
            return expected_count_any(
                eval_boundary_urls, mailbox, start, end, lookup=original_expected
            )

        harness.expected_count = multi_expected  # type: ignore[assignment]
        try:
            records = harness.run_mode("boundaryguard", messages, cfg, proxy_url)
        finally:
            harness.expected_count = original_expected  # type: ignore[assignment]
    finally:
        server.shutdown()

    # Tag mode name for clarity in JSONL.
    for row in records:
        row["mode"] = "boundaryguard_production"
        row["boundary_config"] = "archive_multi_url"
        row["boundary_candidates"] = proxy_cfg.boundary_candidates()

    with out.open("w") as handle:
        for row in records:
            handle.write(json.dumps(row, sort_keys=True) + "\n")

    # Summarize with production mode key.
    summary = harness.summarize(
        [{**row, "mode": "boundaryguard"} for row in records]
    )
    summary["modes"] = {
        "boundaryguard_production": summary["modes"]["boundaryguard"],
    }
    summary["proxy_stats"] = proxy.stats
    summary["sample"] = {
        "recent": False,
        "limit": args.limit,
        "tag": args.tag,
        "boundary_config": "archive_multi_url",
        "boundary_candidates": proxy_cfg.boundary_candidates(),
    }
    summary["elapsed_s"] = time.time() - started
    summary_path.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")

    # Merge with frozen single-boundary Table VII numbers for paper.
    single = json.loads((DATA / "relayer_proxy_live_summary.json").read_text())
    prod = summary["modes"]["boundaryguard_production"]
    single_bg = single["modes"]["boundaryguard"]
    compare = {
        "provenance": "live_natural_observation",
        "workload": "200 evenly spaced delivered Optimism messages",
        "single_boundary": {
            "config": "evaluated single-boundary (paper Table VII prior row)",
            "completed": single_bg["completed"],
            "fail_closed": single_bg["fail_closed"],
            "log_requests": single_bg["requests"],
            "boundary_calls": single["proxy_stats"]["boundary_calls"],
            "kb": round(single_bg["bytes"] / 1024.0, 1),
            "auditable_match": (
                f"{int(single_bg['auditable'] * (single_bg['prefix_complete_of_auditable'] or 0))}"
                f"/{single_bg['auditable']}"
            ),
            "overhead_ms": single_bg["overhead_ms"],
        },
        "production_archive_multi_url": {
            "config": "archive-capable multi-URL boundary fallback",
            "completed": prod["completed"],
            "fail_closed": prod["fail_closed"],
            "log_requests": prod["requests"],
            "boundary_calls": proxy.stats["boundary_calls"],
            "kb": round(prod["bytes"] / 1024.0, 1),
            "auditable_match": (
                f"{int(prod['auditable'] * (prod['prefix_complete_of_auditable'] or 0))}"
                f"/{prod['auditable']}"
            ),
            "overhead_ms": prod["overhead_ms"],
            "unavailable_proxy_stats": proxy.stats.get("unavailable"),
            "boundary_candidates": proxy_cfg.boundary_candidates(),
        },
        "elapsed_s": summary["elapsed_s"],
        "outputs": {
            "jsonl": str(out),
            "summary": str(summary_path),
        },
    }
    compare_path.write_text(json.dumps(compare, indent=2, sort_keys=True) + "\n")
    print(json.dumps(compare, indent=2, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()
